<?php
declare(strict_types=1);require __DIR__.'/app/qhse.php';$user=require_verified();$pageTitle='Signature & Stamp Library';$active='qms';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{if(($_POST['action']??'')==='create'){qhse_signature_save($user,$_POST,$_FILES);flash('success','Signature asset saved for reuse.');}elseif(($_POST['action']??'')==='toggle'){if(!qhse_can_approve($user))throw new DomainException('Your role cannot manage signatures.',403);db()->prepare('UPDATE qhse_signature_assets SET is_active=NOT is_active WHERE id=? AND owner_id=?')->execute([qhse_text($_POST,'id',36,true),$user['owner_id']]);flash('success','Signature status updated.');}redirect('qhse-signatures');}catch(Throwable $e){flash('error',$e instanceof DomainException?$e->getMessage():'The signature asset could not be updated.');redirect('qhse-signatures');}}
$assets=rows('SELECT a.*,u.full_name personnel_name FROM qhse_signature_assets a LEFT JOIN users u ON u.id=a.personnel_user_id WHERE a.owner_id=? ORDER BY a.is_active DESC,a.signatory_name',[$user['owner_id']]);$people=rows('SELECT id,full_name FROM users WHERE owner_id=? AND is_active=1 ORDER BY full_name',[$user['owner_id']]);require __DIR__.'/includes/operations-header.php';?>
<div class="qhse-page-heading"><div><span class="eyebrow">QHSE settings</span><h1>Signatures &amp; stamps</h1><p>Each personnel member can have one reusable signature asset.</p></div><a class="secondary" href="qhse-certificates">Back to certificates</a></div>
<div class="signature-library"><section class="panel"><h2>Add approved asset</h2><form method="post" enctype="multipart/form-data" class="form-grid two"><?= csrf_field() ?><input type="hidden" name="action" value="create"><label>Personnel / user<select name="personnel_user_id"><option value="">Not linked</option><?php foreach($people as $person):?><option value="<?= e($person['id']) ?>"><?= e($person['full_name']) ?></option><?php endforeach;?></select></label><label>Signature name<input name="signatory_name" required></label><label>Title<input name="role_title"></label><label>Signature image<input type="file" name="signature" accept="image/png,image/jpeg"></label><label>Stamp image<input type="file" name="stamp" accept="image/png,image/jpeg"></label><div class="span-2 form-actions"><button class="primary">Save asset</button></div></form></section><section class="panel"><h2>Saved assets</h2><div class="signature-grid"><?php foreach($assets as $asset):?><article><div class="signature-preview"><?php if($asset['signature_data']):?><img src="data:<?= e($asset['signature_mime']) ?>;base64,<?= base64_encode($asset['signature_data']) ?>" alt="<?= e($asset['signatory_name']) ?> signature"><?php endif;?><?php if($asset['stamp_data']):?><img src="data:<?= e($asset['stamp_mime']) ?>;base64,<?= base64_encode($asset['stamp_data']) ?>" alt="<?= e($asset['signatory_name']) ?> stamp"><?php endif;?></div><h3><?= e($asset['signatory_name']) ?></h3><p><?= e($asset['role_title']?:'') ?></p><?= qhse_status_badge($asset['is_active']?'VALID':'REVOKED') ?><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?= e($asset['id']) ?>"><button class="secondary"><?= $asset['is_active']?'Deactivate':'Activate' ?></button></form></article><?php endforeach;?></div><?php if(!$assets):?><div class="qhse-empty"><h3>No saved signatures or stamps</h3><p>Add an approved asset to reuse it during certificate signing.</p></div><?php endif;?></section></div><?php require __DIR__.'/includes/operations-footer.php';?>
